{
  "packet_id": "H6-T03-1",
  "claim_id": "C008",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C008.component",
    "value": "The proposed candidate model represents how documented approval should precede order placement and reach the purchasing record.",
    "scope": "An expected process model for investigation, not a finding about the actual sequence for any order.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P006 explicitly specifies the candidate model's expected sequence and record destination, including permitted alternative record routes."
    }
  },
  "signal_basis": {
    "component_id": "C008.signal_basis",
    "value": "Build a candidate model of approval preceding placement and reaching the purchasing record, including permitted routes through meeting minutes or delegated-authority forms. Compare observed links and timing with route predictions, checking whether approval records link to the order, precede placement and show appropriate authority.",
    "scope": "A proposed investigative model and checks of its predictions; these descriptions do not themselves report historical findings.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        },
