          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans supply the model construction, comparison operation, documentary checks and explicit qualification that observations are proposed rather than reported findings."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C008.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This supported claim describes the proposed model's specified content and requires no unresolved empirical relation."
    }
  },
  "rationale": "The operation explicitly constructs the expected sequence asserted by the claim. Within its investigative scope, the claim is licensed by that construction; it does not assert that any order actually followed the modeled sequence.",
  "uncertainty": "Historical accuracy remains open, but that uncertainty does not undermine this claim about the proposed model's content.",
